const s = $getWorkflowStaticData('global');
s.state = s.state || {
  mode: 'NORMAL', meeting_rooms_locked: false,
  joy_meter: { ours: 0, sinjim: 0, mukhmukh: 0 },
  target_kwd: 200, active_shift: 'A',
  rooms: { room_1: null, room_2: null, room_3: null, room_4: null },
  events: [], last_report: null, celebrate: false
};
const st = s.state;

const b = $input.first().json.body || {};
const kwHour = (new Date().getUTCHours() + 3) % 24;
st.active_shift = (kwHour >= 8 && kwHour < 20) ? 'A' : 'B';
return [{ json: {
  message: String(b.message || 'رتب لي أولويات اليوم'),
  session_id: String(b.session_id || 'ceo'),
  snapshot: { mode: st.mode, joy_meter: st.joy_meter, target_kwd: st.target_kwd, active_shift: st.active_shift, rooms: st.rooms, recent_events: st.events.slice(-8) }
} }];

const s = $getWorkflowStaticData('global');
s.state = s.state || {
  mode: 'NORMAL', meeting_rooms_locked: false,
  joy_meter: { ours: 0, sinjim: 0, mukhmukh: 0 },
  target_kwd: 200, active_shift: 'A',
  rooms: { room_1: null, room_2: null, room_3: null, room_4: null },
  events: [], last_report: null, celebrate: false
};
const st = s.state;

const j = $input.first().json;
const r = j.body || {};
const ev = r.office_event || {};
if (ev.mode) st.mode = ev.mode;
if (ev.meeting_rooms_locked !== undefined) st.meeting_rooms_locked = ev.meeting_rooms_locked;
if (ev.target_kwd) st.target_kwd = ev.target_kwd;
st.celebrate = !!ev.celebrate;
const item = { at: new Date().toISOString(), source: r.source || 'unknown', title: r.title || 'مهمة مكتملة', status: r.status || 'done', icon: ev.icon || '✅', cell_id: ev.cell_id || null };
st.events.push(item);
st.events = st.events.slice(-50);
st.last_report = item;
const esc = x => String(x == null ? '' : x).replace(/[<>&]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' }[c]));
const html = '<div dir="rtl" style="font-family:Tahoma,Arial">'
  + '<h2>' + esc(item.icon) + ' ' + esc(item.title) + '</h2>'
  + '<p><b>الحالة:</b> ' + esc(item.status) + ' | <b>المصدر:</b> ' + esc(item.source) + '</p>'
  + '<p style="white-space:pre-line">' + esc(r.summary) + '</p>'
  + '<h3>التفاصيل</h3><pre style="direction:ltr;text-align:left;background:#f4f4f4;padding:12px;border-radius:8px">' + esc(JSON.stringify(r.details || {}, null, 2)).slice(0, 15000) + '</pre>'
  + '<p>💛💙 فريق QD</p></div>';
return [{ json: {
  ceo_email: j.ceo_email, ceo_phone: j.ceo_phone, twilio_from: j.twilio_from, telegram_chat_id: j.telegram_chat_id,
  title: item.title, status: item.status, summary: String(r.summary || ''), html,
  call: r.call !== false && r.priority !== 'low'
} }];

const s = $getWorkflowStaticData('global');
s.state = s.state || {
  mode: 'NORMAL', meeting_rooms_locked: false,
  joy_meter: { ours: 0, sinjim: 0, mukhmukh: 0 },
  target_kwd: 200, active_shift: 'A',
  rooms: { room_1: null, room_2: null, room_3: null, room_4: null },
  events: [], last_report: null, celebrate: false
};
const st = s.state;

const b = $input.first().json.body || {};
const LEADS = ['قائد الإنتاج', 'قائد مختبر المتعة', 'قائد الابتكار', 'قائد الموارد البشرية', 'قائد التسويق', 'مدرب المهارات', 'مدير الأعمال'];
const room = ['room_1', 'room_2', 'room_3', 'room_4'].includes(b.room) ? b.room : 'room_1';
const action = b.action || 'open';
if (action === 'close') { st.rooms[room] = null; return [{ json: { ok: true, room, message: 'تم إنهاء الاجتماع' } }]; }
const summoned = (b.summoned_names || []).map(String);
const requested = (b.attendees || []).map(String);
const admitted = [], denied = [];
for (const name of requested.concat(summoned)) {
  if (LEADS.includes(name) || summoned.includes(name)) { if (!admitted.includes(name)) admitted.push(name); }
  else denied.push(name);
}
const isCrisis = st.mode === 'CODE_RED_JOY_CRISIS';
st.rooms[room] = { topic: b.topic || (isCrisis ? 'CODE_RED_JOY_CRISIS' : 'اجتماع بالطلب'), attendees: admitted, opened_at: new Date().toISOString(), locked: isCrisis };
st.events.push({ at: new Date().toISOString(), source: 'meeting', title: 'اجتماع في ' + room, icon: '🗓️' });
return [{ json: { ok: true, room, admitted, denied, locked: isCrisis,
  message: denied.length ? 'منع دخول: ' + denied.join('، ') + ' (الدخول للقادة أو بالاستدعاء بالاسم فقط)' : 'تم فتح الاجتماع' } }];

const s = $getWorkflowStaticData('global');
s.state = s.state || {
  mode: 'NORMAL', meeting_rooms_locked: false,
  joy_meter: { ours: 0, sinjim: 0, mukhmukh: 0 },
  target_kwd: 200, active_shift: 'A',
  rooms: { room_1: null, room_2: null, room_3: null, room_4: null },
  events: [], last_report: null, celebrate: false
};
const st = s.state;

const kwHour = (new Date().getUTCHours() + 3) % 24;
st.active_shift = (kwHour >= 8 && kwHour < 20) ? 'A' : 'B';
return [{ json: { ...st, server_time: new Date().toISOString() } }];

const s = $getWorkflowStaticData('global');
s.state = s.state || {
  mode: 'NORMAL', meeting_rooms_locked: false,
  joy_meter: { ours: 0, sinjim: 0, mukhmukh: 0 },
  target_kwd: 200, active_shift: 'A',
  rooms: { room_1: null, room_2: null, room_3: null, room_4: null },
  events: [], last_report: null, celebrate: false
};
const st = s.state;

const b = $input.first().json.body || {};
const allowed = ['mode', 'meeting_rooms_locked', 'joy_meter', 'target_kwd', 'celebrate', 'joy_round'];
for (const k of allowed) if (b[k] !== undefined) st[k] = b[k];
if (b.event) { st.events.push({ at: new Date().toISOString(), ...b.event }); st.events = st.events.slice(-50); }
return [{ json: { ok: true, state: st } }];
